#!/usr/bin/env bash
set -euo pipefail

# Generated by fallow setup-hooks.
# Installer version: @@FALLOW_INSTALLER_VERSION@@
# Requires bash and fallow. Older installations can use jq as a fallback.
# On Windows run via git-bash or WSL.
# Native JSON protocol: fallow-gate-json-v1
# Blocks Claude Code and Codex git commit and git push when fallow audit
# returns verdict fail. Both harnesses send the PreToolUse payload on stdin and
# treat exit 2 as a block.
# Runtime errors fail open with a single stderr notice so skips stay visible.
# Set FALLOW_GATE_DEBUG=1 to also log when a command is skipped because it is
# not classified as a git commit or push.
#
# Block message. On a block the gate prints one line for each finding that
# caused the block (the findings with `introduced: true`, or every finding
# under `gate = "all"`), the verdict, and the path of the full JSON report.
# The gate writes that report to .fallow/gate-report.json in the audited
# tree. Set FALLOW_GATE_REPORT to write it to another path (a relative path
# resolves against the audited tree). Set FALLOW_GATE_OUTPUT=json to print the
# full JSON report on stderr instead, which is the output of older fallow
# versions.
# The gate does not write through a symbolic link. When the report path or a
# directory of a relative report path is a link, the block message names a
# temporary copy of the report. When .fallow/.gitignore is a link, the gate
# does not write it.
#
# Version floor (FALLOW_GATE_MIN_VERSION, default 2.85.0). The gate passes
# --gate-marker agent (added in v2.85.0) so Impact can record containment;
# older binaries reject the flag entirely, which would make every audit fail
# open. The floor also covers the older uncommitted-changes inclusion fix
# (aabb8e1b, v2.46.0). Set the env var to the empty string to disable.
# Floor comparison uses `sort -V`; GNU and BSD agree on plain semver but
# diverge on prereleases (BSD sorts `2.48.0-alpha.1` ABOVE `2.48.0`, GNU below).
# If you set a prerelease floor explicitly, verify the behavior on the target OS.

# The longest hook input, in characters, for the small reader and for the
# quote-aware subshell scan below. A longer input goes to jq or to the JSON
# reader of fallow, because the time of those shell scans grows faster than
# the length.
GATE_SMALL_INPUT_LIMIT=8192
GATE_NL=$'\n'

gate_skip_not_git_write() {
  if [ -n "${FALLOW_GATE_DEBUG:-}" ]; then
    echo "fallow-gate: not a git commit/push, skipping audit." >&2
  fi
  exit 0
}

# The hook runs on every Bash tool call. The gate reads the hook input with
# the read builtin and keeps it in a variable. A plain pattern on the raw hook
# input then skips a command that cannot be a git commit or push, before the
# gate starts any program. A git write puts `git` before `commit`, `push` or
# an expansion in the command text. The match drops quote and backslash
# characters first, as gate_loose_write does, so `g''it commit` still goes to
# the exact parse. A JSON `\u` escape can hide a word, so such a hook input
# always goes there too. A hook input over GATE_SMALL_INPUT_LIMIT characters
# also goes to the exact parse.
INPUT=""
IFS= read -r -d '' INPUT || true
INPUT="${INPUT%$'\n'}"
if [ "${#INPUT}" -le "$GATE_SMALL_INPUT_LIMIT" ]; then
  case "$INPUT" in
    *'\u'*) ;;
    *)
      case "${INPUT//[\'\"\\]/}" in
        *git*commit* | *git*push* | *git*'$'*) ;;
        *) gate_skip_not_git_write ;;
      esac
      ;;
  esac
fi

# PATH rules. The gate looks up every program, also cat, git and jq, only in
# an absolute PATH entry. The entry has no node_modules component (in any
# letter case), before or after links, and it is not below an excluded tree:
# the tree of the process directory, of the install root (project scope), of
# the session directory, the git top level of the session, and the tree of
# each audit root. An empty or relative entry names a directory below the
# working directory, and a package manager or a tool such as direnv puts a
# directory of the project on PATH. The tree of a directory is the union of
# the nearest directory with a .git entry and its git top level. The
# functions use shell builtins and no subshell, so the gate filters PATH
# before each new tree can run a program. An entry of GATE_EXCLUDED that
# starts with `=` excludes only that one directory, not the directories
# below it.
GATE_EXCLUDED=()
GATE_TARGET_EXCLUDED=()
GATE_PATH_ENTRIES=()
GATE_PATH_REAL=()

# Sets RESOLVED to the physical path of directory $1. Returns 1 when $1 is
# empty or is not a directory.
gate_resolve_dir() {
  local back="$PWD"
  RESOLVED=""
  [ -n "$1" ] || return 1
  CDPATH='' cd -P -- "$1" 2>/dev/null || return 1
  RESOLVED="$PWD"
  if ! CDPATH='' cd -- "$back" 2>/dev/null; then
    echo "fallow-gate: cannot return to $back, skipping audit." >&2
    exit 0
  fi
}

# Returns 0 when path $1 is directory $2 or a path below it, in any letter
# case.
gate_inside() {
  local dir="${1%/}/" tree="${2%/}/" found=1
  shopt -s nocasematch
  case "$dir" in
    "$tree"*) found=0 ;;
  esac
  shopt -u nocasematch
  return "$found"
}

# Returns 0 when directory $1 is excluded.
gate_excluded() {
  local tree
  for tree in ${GATE_EXCLUDED[@]+"${GATE_EXCLUDED[@]}"} ${GATE_TARGET_EXCLUDED[@]+"${GATE_TARGET_EXCLUDED[@]}"}; do
    case "$tree" in
      /) ;;
      =*) ! { gate_inside "$1" "${tree#=}" && gate_inside "${tree#=}" "$1"; } || return 0 ;;
      *) ! gate_inside "$1" "$tree" || return 0 ;;
    esac
  done
  return 1
}

# Sets PATH to the entries that the rules keep. When no entry stays, PATH
# names a directory with no programs, because an empty PATH searches the
# current directory.
gate_filter_path() {
  local i out=""
  for i in ${GATE_PATH_ENTRIES[@]+"${!GATE_PATH_ENTRIES[@]}"}; do
    gate_excluded "${GATE_PATH_REAL[$i]}" && continue
    gate_excluded "${GATE_PATH_ENTRIES[$i]}" && continue
    out="${out:+$out:}${GATE_PATH_ENTRIES[$i]}"
  done
  PATH="${out:-/var/empty}"
}

# Adds the trees of directory $1 to GATE_EXCLUDED and filters PATH again. $2
# is the git top level when the caller knows it. Without a .git entry at or
# above $1, the tree is $1 itself when $3 is `self`. A tree that is HOME or
# `/`, for a directory below it, becomes that directory, so a git repository
# of the home folder keeps the user tools below HOME in use. A tree that is
# `/`, or HOME without a .git entry, for that same directory, excludes only
# that one directory.
gate_exclude_tree() {
  local dir="$1" tree home=""
  local -a found=()
  [ -n "$dir" ] || return 0
  ! gate_resolve_dir "$dir" || dir="$RESOLVED"
  tree="$dir"
  while [ ! -e "$tree/.git" ]; do
    if [ -z "$tree" ] || [ "$tree" = / ]; then
      tree=""
      break
    fi
    tree="${tree%/*}"
    [ -n "$tree" ] || tree=/
  done
  if [ -n "$tree" ]; then
    found+=("$tree")
  elif [ "${3:-}" = self ]; then
    found+=("$dir")
  fi
  if [ -n "${2:-}" ]; then
    if gate_resolve_dir "$2"; then found+=("$RESOLVED"); else found+=("$2"); fi
  fi
  ! gate_resolve_dir "${HOME:-}" || home="$RESOLVED"
  for tree in ${found[@]+"${found[@]}"}; do
    if [ "$tree" = / ] || { [ -n "$home" ] && gate_inside "$tree" "$home" && gate_inside "$home" "$tree"; }; then
      if ! gate_inside "$tree" "$dir"; then
        tree="$dir"
      elif [ "$tree" = / ] || [ ! -e "$home/.git" ]; then
        tree="=$dir"
      fi
    fi
    GATE_EXCLUDED+=("$tree")
  done
  gate_filter_path
}

# Reads the absolute PATH entries without a node_modules component once, with
# the physical directory of each.
gate_read_path() {
  local entry
  local -a entries=()
  IFS=: read -r -a entries <<<"${PATH:-}"
  shopt -s nocasematch
  for entry in ${entries[@]+"${entries[@]}"}; do
    case "$entry" in
      node_modules | node_modules/* | */node_modules | */node_modules/*) continue ;;
      /* | [A-Za-z]:[\\/]*) ;;
      *) continue ;;
    esac
    shopt -u nocasematch
    gate_resolve_dir "$entry" || { shopt -s nocasematch; continue; }
    shopt -s nocasematch
    case "/$RESOLVED/" in
      */node_modules/*) continue ;;
    esac
    GATE_PATH_ENTRIES+=("$entry")
    GATE_PATH_REAL+=("$RESOLVED")
  done
  shopt -u nocasematch
}
gate_read_path
export PATH

# The trees of the git write targets and of the audit roots leave PATH too,
# in GATE_TARGET_EXCLUDED. GATE_TARGETS keeps each such directory for the
# block message of gate_check_targets.
GATE_TARGETS=()
gate_exclude_target() {
  local n="${#GATE_EXCLUDED[@]}" i
  GATE_TARGETS+=("$1")
  gate_exclude_tree "$1" ""
  for ((i = n; i < ${#GATE_EXCLUDED[@]}; i++)); do
    GATE_TARGET_EXCLUDED+=("${GATE_EXCLUDED[$i]}")
  done
  if [ "$n" -eq 0 ]; then
    GATE_EXCLUDED=()
  else
    GATE_EXCLUDED=("${GATE_EXCLUDED[@]:0:n}")
  fi
}

# Blocks the command when the trees of the targets hold the fallow or the git
# that the gate finds without them. The audit cannot then run with a program
# that the gate trusts.
gate_check_targets() {
  local tool before after target name
  local -a saved=(${GATE_TARGET_EXCLUDED[@]+"${GATE_TARGET_EXCLUDED[@]}"})
  for tool in fallow git; do
    GATE_TARGET_EXCLUDED=()
    gate_filter_path
    before="$(gate_which "$tool" || true)"
    GATE_TARGET_EXCLUDED=(${saved[@]+"${saved[@]}"})
    gate_filter_path
    after="$(gate_which "$tool" || true)"
    [ -n "$before" ] && [ "$after" != "$before" ] || continue
    name=""
    if gate_resolve_dir "${before%/*}"; then
      before="$RESOLVED/${before##*/}"
      for target in ${GATE_TARGETS[@]+"${GATE_TARGETS[@]}"}; do
        if gate_resolve_dir "$target" && gate_inside "${before%/*}" "$RESOLVED"; then
          name="$target"
          break
        fi
      done
    fi
    {
      echo "fallow-gate: blocked: the git write targets ${name:-a tree} that holds the $tool on PATH ($before)."
      echo "fallow-gate: the gate does not run a program from a tree that it audits, so the audit cannot run."
    } >&2
    exit 2
  done
}

# Prints the absolute path of the program $1 on PATH, or returns 1.
gate_which() {
  local found
  found="$(command -v "$1" 2>/dev/null)" || return 1
  case "$found" in
    /* | [A-Za-z]:[\\/]*) printf '%s\n' "$found" ;;
    *) return 1 ;;
  esac
}

# The install scope and the fallow of this gate. Fallow writes both values
# when it installs the script. A user-scope gate runs the fallow that the
# install recorded (GATE_FALLOW_BIN), else the fallow on PATH. A
# project-scope gate runs the launcher of the project that holds this script
# (the install root, two directories above the script), else the fallow on
# PATH. The gate does not run a launcher of the session directory or of its
# parents. A value that fallow did not write counts as the user scope with no
# recorded fallow.
GATE_SCOPE='@@FALLOW_GATE_SCOPE@@'
GATE_FALLOW_BIN='@@FALLOW_GATE_BIN@@'

GATE_INSTALL_ROOT=""
GATE_LOCAL_FALLOW=""
GATE_SCRIPT_DIR="${BASH_SOURCE[0]%/*}"
[ "$GATE_SCRIPT_DIR" != "${BASH_SOURCE[0]}" ] || GATE_SCRIPT_DIR=.
if [ "$GATE_SCOPE" = project ] && gate_resolve_dir "$GATE_SCRIPT_DIR/../.."; then
  GATE_INSTALL_ROOT="$RESOLVED"
fi
# No program runs before this filter.
gate_exclude_tree "$PWD" "" self
gate_exclude_tree "$GATE_INSTALL_ROOT" "" self
if [ "$GATE_SCOPE" = project ]; then
  if [ -n "$GATE_INSTALL_ROOT" ] && [ -x "$GATE_INSTALL_ROOT/node_modules/.bin/fallow" ]; then
    GATE_LOCAL_FALLOW="$GATE_INSTALL_ROOT/node_modules/.bin/fallow"
  fi
else
  case "$GATE_FALLOW_BIN" in
    /* | [A-Za-z]:[\\/]*) [ -x "$GATE_FALLOW_BIN" ] && GATE_LOCAL_FALLOW="$GATE_FALLOW_BIN" ;;
  esac
fi

# Every git call of the gate refuses a bare repository that git finds on its
# own. A directory of the analyzed tree can have the shape of a bare
# repository, and its config could then name another work tree.
gate_git() {
  git -c safe.bareRepository=explicit "$@"
}

GATE_PATH_FALLOW="$(gate_which fallow || true)"

GATE_JSON_RUNNER=()
GATE_JSON_DIR=""

gate_json() {
  (CDPATH='' cd -P "$GATE_JSON_DIR" && "${GATE_JSON_RUNNER[@]}" hooks gate-runtime "$@")
}

gate_try_json_runner() {
  local anchor="$1" probe
  shift
  # A probe never gets the hook stdin, so a launcher cannot read the payload.
  probe="$(CDPATH='' cd -P "$anchor" && "$@" hooks gate-runtime probe </dev/null 2>/dev/null)" || return 1
  [ "$probe" = fallow-gate-json-v1 ] || return 1
  GATE_JSON_DIR="$anchor"
  GATE_JSON_RUNNER=("$@")
}

# The reader uses the order of the audit runner below: the trusted fallow of
# the install, then the fallow on PATH, then the package manager of the
# install root (project scope only).
gate_find_json_runner() {
  local anchor
  if [ -n "$GATE_LOCAL_FALLOW" ] && gate_try_json_runner "$PWD" "$GATE_LOCAL_FALLOW"; then
    return 0
  fi
  if [ -n "$GATE_PATH_FALLOW" ] && gate_try_json_runner "$PWD" "$GATE_PATH_FALLOW"; then
    return 0
  fi
  anchor="$GATE_INSTALL_ROOT"
  [ -n "$anchor" ] && [ -f "$anchor/package.json" ] || return 1
  if command -v yarn >/dev/null 2>&1 && gate_try_json_runner "$anchor" yarn exec fallow --; then
    return 0
  fi
  command -v npx >/dev/null 2>&1 && gate_try_json_runner "$anchor" npx --no-install fallow
}

# Decodes the JSON string escapes of $1 into GATE_STR. A `\u` escape or an
# unknown escape returns 1.

GATE_STR=""
gate_json_unescape() {
  local s="$1" c
  GATE_STR=""
  while [[ "$s" == *\\* ]]; do
    GATE_STR+="${s%%\\*}"
    s="${s#*\\}"
    c="${s:0:1}"
    s="${s:1}"
    case "$c" in
      '"' | \\ | /) GATE_STR+="$c" ;;
      b) GATE_STR+=$'\b' ;;
      f) GATE_STR+=$'\f' ;;
      n) GATE_STR+=$'\n' ;;
      r) GATE_STR+=$'\r' ;;
      t) GATE_STR+=$'\t' ;;
      *) return 1 ;;
    esac
  done
  GATE_STR+="$s"
}

# Reads `.tool_input.command` and `.cwd` from the hook input in INPUT into
# CMD and SESSION_CWD without a helper program. Returns 1 for a hook input
# that this small reader does not decode, for example one with a `\u` escape. The
# caller then uses a JSON reader.
gate_read_input() {
  local rest="$INPUT" depth=0 want_key=0 top
  local str_re='^"(([^"\\]|\\.)*)"' scalar_re='^(-?[0-9][0-9.eE+-]*|true|false|null)'
  local -a kinds=("") keys=("")
  CMD=""
  SESSION_CWD=""
  while :; do
    [[ "$rest" =~ ^[[:space:]]+ ]] && rest="${rest:${#BASH_REMATCH[0]}}"
    [ -n "$rest" ] || break
    top="${kinds[$depth]}"
    case "${rest:0:1}" in
      '{' | '[')
        # A command that is not a string goes to the JSON reader.
        [ "$depth" -eq 2 ] && [ "${keys[1]}" = tool_input ] && [ "$top" = o ] &&
          [ "$want_key" -eq 0 ] && [ "${keys[2]}" = command ] && return 1
        depth=$((depth + 1))
        if [ "${rest:0:1}" = '{' ]; then
          kinds[depth]=o
          want_key=1
        else
          kinds[depth]=a
          want_key=0
        fi
        keys[depth]=""
        rest="${rest:1}"
        ;;
      '}' | ']')
        [ "$depth" -gt 0 ] || return 1
        if [ "${rest:0:1}" = '}' ]; then
          [ "$top" = o ] || return 1
        else
          [ "$top" = a ] || return 1
        fi
        depth=$((depth - 1))
        want_key=0
        rest="${rest:1}"
        ;;
      ,)
        [ "$depth" -gt 0 ] || return 1
        [ "$top" = o ] && want_key=1
        rest="${rest:1}"
        ;;
      :)
        rest="${rest:1}"
        ;;
      '"')
        [[ "$rest" =~ $str_re ]] || return 1
        rest="${rest:${#BASH_REMATCH[0]}}"
        gate_json_unescape "${BASH_REMATCH[1]}" || return 1
        if [ "$top" = o ] && [ "$want_key" -eq 1 ]; then
          keys[depth]="$GATE_STR"
          want_key=0
        elif [ "$depth" -eq 1 ] && [ "${keys[1]}" = cwd ]; then
          SESSION_CWD="$GATE_STR"
        elif [ "$depth" -eq 2 ] && [ "${keys[1]}" = tool_input ] && [ "$top" = o ] &&
          [ "${keys[2]}" = command ]; then
          CMD="$GATE_STR"
        fi
        ;;
      *)
        [[ "$rest" =~ $scalar_re ]] || return 1
        # A command that is not a string goes to the JSON reader.
        [ "$depth" -eq 2 ] && [ "${keys[1]}" = tool_input ] && [ "${keys[2]}" = command ] && return 1
        rest="${rest:${#BASH_REMATCH[0]}}"
        ;;
    esac
  done
  [ "$depth" -eq 0 ] && [ "${kinds[1]:-}" = o ]
}


# Tokenize instead of matching one regex so git-level options between `git`
# and the subcommand (git -c k=v commit, git -C dir push, git --no-pager
# commit, git --git-dir=/x push) still route into the audit, while subcommand
# lookalikes in arguments (git log commit-message.txt) do not. See issue #2106.
#
# The scan also collects GIT_WRITE_CANDIDATES: the directories that a git
# write may target (`cd <dir>` before it, `-C`, `--work-tree`, the parent of a
# `--git-dir` that ends in .git, and the same two as `GIT_WORK_TREE` and
# `GIT_DIR` prefixes). The word split is simple, so a candidate can
# be wrong. A candidate only adds an audit: the session tree is audited too,
# unless gate_allowlisted_target below proves the target.
GIT_WRITE_CANDIDATES=()

gate_unquote() {
  local word="$1"
  case "$word" in
    \'*\' | \"*\") word="${word:1:${#word}-2}" ;;
  esac
  printf '%s\n' "$word"
}

# Prints the parent directory of path $1, as dirname does for a path without
# a trailing slash.
gate_parent() {
  case "$1" in
    /*/*) printf '%s\n' "${1%/*}" ;;
    /*) printf '/\n' ;;
    */*) printf '%s\n' "${1%/*}" ;;
    *) printf '.\n' ;;
  esac
}

gate_join() {
  case "$2" in
    /*) printf '%s\n' "$2" ;;
    *) printf '%s\n' "${1:+$1/}$2" ;;
  esac
}

# Prints $1 with each `(` and `)` of a subshell or a command substitution on
# its own line as $2 or $3. A parenthesis inside single or double quotes, or
# after a backslash, stays text. A `$(` inside double quotes starts a command
# substitution, and its `)` returns to the double quotes.
gate_mark_subshells() {
  local LC_ALL=C
  local s="$1" open="$2" close="$3" nl=$'\n' quote="" stack="" c
  local i=0 start=0 n=${#1}
  local -a parts=()
  while [ "$i" -lt "$n" ]; do
    c="${s:i:1}"
    if [ "$quote" = "'" ]; then
      [ "$c" != "'" ] || quote=""
    elif [ "$quote" = '"' ]; then
      case "$c" in
        '"') quote="" ;;
        \\) i=$((i + 1)) ;;
        '$')
          if [ "${s:i+1:1}" = '(' ]; then
            i=$((i + 1))
            parts+=("${s:start:i-start}" "$nl$open$nl")
            start=$((i + 1))
            stack+=q
            quote=""
          fi
          ;;
      esac
    else
      case "$c" in
        "'" | '"') quote="$c" ;;
        \\) i=$((i + 1)) ;;
        '(')
          parts+=("${s:start:i-start}" "$nl$open$nl")
          start=$((i + 1))
          stack+=u
          ;;
        ')')
          parts+=("${s:start:i-start}" "$nl$close$nl")
          start=$((i + 1))
          [ "${stack: -1}" != q ] || quote='"'
          stack="${stack%?}"
          ;;
      esac
    fi
    i=$((i + 1))
  done
  parts+=("${s:start}")
  printf '%s' "${parts[@]}"
}

is_git_write_command() {
  local cmd="$1" segment cd_dir="" dir value found=1 track=1 separators=';|&'
  local open_mark=$'\001(' close_mark=$'\001)'
  local -a saved_dirs=()
  GIT_WRITE_CANDIDATES=()
  # Each `cd` target is an audit candidate, also a `cd` in a subshell. A `cd`
  # in a subshell does not change the directory of the later commands, so `(`
  # saves the directory and `)` restores it. An unmatched `)` keeps it. A
  # command over GATE_SMALL_INPUT_LIMIT characters, or one with ANSI-C quotes,
  # a `#`, a `case` or a here-document, has no quote-aware scan: there each
  # parenthesis is only a separator, and the directory stays.
  [ "${#cmd}" -le "$GATE_SMALL_INPUT_LIMIT" ] || track=0
  case "$cmd" in
    *"\$'"* | *'#'* | *case* | *'<<'*) track=0 ;;
  esac
  if [ "$track" -eq 1 ]; then
    cmd="$(gate_mark_subshells "$cmd" "$open_mark" "$close_mark")"
  else
    separators=';|&()'
  fi
  # Control operators separate simple commands; each becomes its own line.
  while IFS= read -r segment; do
    if [ "$segment" = "$open_mark" ]; then
      saved_dirs+=("$cd_dir")
      continue
    fi
    if [ "$segment" = "$close_mark" ]; then
      if [ "${#saved_dirs[@]}" -gt 0 ]; then
        cd_dir="${saved_dirs[${#saved_dirs[@]}-1]}"
        unset 'saved_dirs[${#saved_dirs[@]}-1]'
      fi
      continue
    fi
    # Intentional word splitting; globbing is disabled below.
    # shellcheck disable=SC2086
    set -- $segment
    if [ "$#" -ge 2 ] && [ "$1" = cd ]; then
      cd_dir="$(gate_join "$cd_dir" "$(gate_unquote "$2")")"
      GIT_WRITE_CANDIDATES+=("$cd_dir")
    fi
    while [ "$#" -gt 0 ]; do
      if [ "$1" != "git" ]; then
        # A git location prefix names a candidate too.
        case "$1" in
          GIT_WORK_TREE=?*)
            GIT_WRITE_CANDIDATES+=("$(gate_join "$cd_dir" "$(gate_unquote "${1#*=}")")")
            ;;
          GIT_DIR=?*)
            value="$(gate_unquote "${1#*=}")"
            value="${value%/}"
            if [ "${value##*/}" = .git ]; then
              GIT_WRITE_CANDIDATES+=("$(gate_join "$cd_dir" "$(gate_parent "$value")")")
            fi
            ;;
        esac
        shift
        continue
      fi
      shift
      dir="$cd_dir"
      while [ "$#" -gt 0 ]; do
        value="${2:-}"
        case "$1" in
          commit | push)
            found=0
            [ -n "$dir" ] && GIT_WRITE_CANDIDATES+=("$dir")
            break
            ;;
          -C | --work-tree | --git-dir)
            value="$(gate_unquote "$value")"
            ;;
          --work-tree=* | --git-dir=*)
            value="$(gate_unquote "${1#*=}")"
            set -- "${1%%=*}" "$value" "${@:2}"
            ;;
          -c | --namespace | --config-env | --super-prefix | --exec-path | --list-cmds | --attr-source)
            # Global option whose value arrives as the next word.
            shift
            [ "$#" -gt 0 ] && shift
            continue
            ;;
          -*)
            # Value-less global option (--no-pager) or inline-value form
            # (-cuser.name=x).
            shift
            continue
            ;;
          *)
            # A different subcommand; resume scanning for a later `git` word.
            break
            ;;
        esac
        case "$1" in
          -C) dir="$(gate_join "$dir" "$value")" ;;
          --work-tree) GIT_WRITE_CANDIDATES+=("$(gate_join "$dir" "$value")") ;;
          --git-dir)
            value="${value%/}"
            if [ "${value##*/}" = .git ]; then
              GIT_WRITE_CANDIDATES+=("$(gate_join "$dir" "$(gate_parent "$value")")")
            fi
            ;;
        esac
        shift
        [ "$#" -gt 0 ] && shift
      done
      [ "$#" -gt 0 ] && shift
    done
  done <<<"${cmd//[$separators]/$GATE_NL}"
  return "$found"
}

# A coarse second check for a command with quotes, escapes or expansions,
# which the scan above can split wrong (`git -C "a b" commit`, `bash -c 'git
# push'`, `eval "git commit"`). It drops the quote and escape characters and
# counts a `git` word followed later by a `commit` or `push` word in the same
# simple command. Parentheses become spaces, so `git -C "$(pwd)" commit`
# stays one command. It can count a command that does not write: that only adds
# an audit.
gate_loose_write() {
  local text="$1" segment word seen_git line_join=$'\\\n'
  case "$text" in
    *[\'\"\\\$\`]*) ;;
    *) return 1 ;;
  esac
  text="${text//"$line_join"/ }"
  text="${text//[\'\"\\]/}"
  text="${text//[;|&\`]/$GATE_NL}"
  text="${text//[()]/ }"
  while IFS= read -r segment; do
    seen_git=0
    # Intentional word splitting; globbing is disabled below.
    # shellcheck disable=SC2086
    for word in $segment; do
      if [ "$word" = git ]; then
        seen_git=1
        continue
      fi
      # A subcommand from an expansion (`git $cmd`) can be a write too.
      [ "$seen_git" -eq 1 ] && [ "${word:0:1}" = '$' ] && return 0
      [ "$seen_git" -ne 0 ] && seen_git=2
      if [ "$seen_git" -eq 2 ] && { [ "$word" = commit ] || [ "$word" = push ]; }; then
        return 0
      fi
    done
  done <<<"$text"
  return 1
}

# The exact check below reads `tool_input.command` before the gate starts any
# fallow. The small reader above decodes a hook input up to
# GATE_SMALL_INPUT_LIMIT characters; its work grows with the square of the
# length. jq or the trusted
# JSON reader of the install decodes the rest.
CMD=""
SESSION_CWD=""
if [ "${#INPUT}" -le "$GATE_SMALL_INPUT_LIMIT" ] && gate_read_input; then
  :
elif command -v jq >/dev/null 2>&1; then
  CMD="$(jq -r '.tool_input.command // empty' <<<"$INPUT")"
  SESSION_CWD="$(jq -r '.cwd // empty' <<<"$INPUT" 2>/dev/null || true)"
else
  gate_find_json_runner || true
  if [ "${#GATE_JSON_RUNNER[@]}" -eq 0 ]; then
    echo "fallow-gate: no native JSON reader or jq found, skipping audit. Upgrade fallow on PATH or install it in the project." >&2
    exit 0
  fi
  GATE_INPUT="$(mktemp)"
  if ! gate_json input <<<"$INPUT" >"$GATE_INPUT"; then
    rm -f "$GATE_INPUT"
    echo "fallow-gate: invalid tool input, skipping audit." >&2
    exit 0
  fi
  {
    IFS= read -r -d '' CMD
    IFS= read -r -d '' SESSION_CWD
  } <"$GATE_INPUT"
  rm -f "$GATE_INPUT"
fi
# The session tree is known now. A JSON reader of the hook input above ran
# only from a PATH that the trees of the process directory and of the install
# root do not supply.
if [ -n "$SESSION_CWD" ] && [ -d "$SESSION_CWD" ]; then
  gate_exclude_tree "$SESSION_CWD" "" self
  GATE_PATH_FALLOW="$(gate_which fallow || true)"
fi

set -f
if is_git_write_command "$CMD" || gate_loose_write "$CMD"; then
  GIT_WRITE=1
else
  GIT_WRITE=0
fi
set +f
if [ "$GIT_WRITE" -eq 0 ]; then
  gate_skip_not_git_write
fi
GATE_CANDIDATE_BASE="$PWD"
if [ -n "$SESSION_CWD" ] && gate_resolve_dir "$SESSION_CWD"; then
  GATE_CANDIDATE_BASE="$RESOLVED"
fi
for GATE_CANDIDATE in ${GIT_WRITE_CANDIDATES[@]+"${GIT_WRITE_CANDIDATES[@]}"}; do
  gate_exclude_target "$(gate_join "$GATE_CANDIDATE_BASE" "$GATE_CANDIDATE")"
done

# The block message reads the audit report with the same reader.
if [ "${#GATE_JSON_RUNNER[@]}" -eq 0 ]; then
  gate_find_json_runner || true
fi
if [ "${#GATE_JSON_RUNNER[@]}" -eq 0 ] && ! command -v jq >/dev/null 2>&1; then
  echo "fallow-gate: no native JSON reader or jq found, skipping audit. Upgrade fallow on PATH or install it in the project." >&2
  exit 0
fi

# The hook process can start in a directory that is not the session directory.
# For example, a session in a nested git worktree can get a hook process in the
# main checkout. The audit must run against the tree of the session. The hook
# input gives the session directory in its `cwd` field. The gate below finds
# the start directory: the session directory, or for a git write in a strict
# grammar, the tree that the write targets. From a start directory the audit
# root is:
#   1. The nearest directory at or above the start directory that holds this
#      script at the same relative location (.claude/hooks/fallow-gate.sh or
#      .codex/hooks/fallow-gate.sh). The walk stops at the first .git entry,
#      the same rule as the generated handler. The install root can be below
#      the git root (`--root packages/app`), so this step comes first. The walk
#      ignores $HOME, because a script there is the user-scope install.
#   2. Else, when the session directory is in a git work tree: the directory of
#      the hook process when it is in that work tree, as before. A package
#      directory with its own fallow config thus stays the audit root. When the
#      process directory is in another work tree (outside it, or a nested
#      worktree or submodule below it), the audit root is the git top level. A git top level equal to $HOME does
#      not count, so a home directory under git never becomes the audit root.
#   3. Else the session directory.
# All paths are physical (`pwd -P`), so a symlink cannot move the walk into the
# parents of the link. When `cwd` is missing, empty or not a directory, the
# audit runs in the directory of the process, as before.
physical_dir() {
  CDPATH='' cd -P "$1" 2>/dev/null && pwd -P
}

gate_relative_path() {
  local script_dir harness_dir
  script_dir="$(CDPATH='' cd "$(dirname "${BASH_SOURCE[0]}")" 2>/dev/null && pwd)" || return 0
  [ "$(basename "$script_dir")" = hooks ] || return 0
  harness_dir="$(basename "$(dirname "$script_dir")")"
  case "$harness_dir" in
    .claude | .codex)
      printf '%s\n' "$harness_dir/hooks/fallow-gate.sh"
      ;;
  esac
}

resolve_audit_root() {
  local session_dir="$1" gate_rel="$2" process_dir="$3" home_dir="$4" dir parent top process_top
  dir="$session_dir"
  if [ -n "$gate_rel" ]; then
    while :; do
      if [ -f "$dir/$gate_rel" ] && [ "$dir" != "$home_dir" ]; then
        printf '%s\n' "$dir"
        return 0
      fi
      [ -e "$dir/.git" ] && break
      parent="$(dirname "$dir")"
      # A path that is its own parent is the file system root.
      [ "$parent" = "$dir" ] && break
      dir="$parent"
    done
  fi
  if top="$(gate_git -C "$session_dir" rev-parse --show-toplevel 2>/dev/null)" && [ -n "$top" ] &&
    top="$(physical_dir "$top")" && [ "$top" != "$home_dir" ]; then
    # A path under the top level is not enough: a nested worktree, submodule
    # or nested repository below it is another work tree. Keep the process
    # directory only when its own git top level is the same work tree.
    process_top="$(gate_git -C "$process_dir" rev-parse --show-toplevel 2>/dev/null || true)"
    if [ -n "$process_top" ] && process_top="$(physical_dir "$process_top")" &&
      [ "$process_top" = "$top" ]; then
      printf '%s\n' "$process_dir"
    else
      printf '%s\n' "$top"
    fi
    return 0
  fi
  printf '%s\n' "$session_dir"
}

PROCESS_DIR="$(pwd -P 2>/dev/null || pwd)"
SESSION_DIR=""
if [ -n "$SESSION_CWD" ] && [ -d "$SESSION_CWD" ]; then
  # `cd` and `pwd` give an absolute path, also for a Windows path in git-bash.
  SESSION_DIR="$(physical_dir "$SESSION_CWD" || true)"
fi
HOME_DIR=""
if [ -n "${HOME:-}" ]; then
  HOME_DIR="$(physical_dir "$HOME" || true)"
fi
GATE_REL="$(gate_relative_path)"
BASE_DIR="${SESSION_DIR:-$PROCESS_DIR}"
# The directory of the shell as it names it, for a logical `cd`.
LOGICAL_BASE="$PROCESS_DIR"
if [ -n "$SESSION_DIR" ]; then
  LOGICAL_BASE="$SESSION_CWD"
fi

# Prints three lines for a directory, as git finds them: the work tree top
# level, the git directory and the common git directory. Linked worktrees of
# one repository have their own top level and git directory but share the
# common git directory, with its refs. Git also skips an empty `.git`
# directory and follows a gitfile.
gate_git_identity() {
  local out top git_dir common
  out="$(gate_git -C "$1" rev-parse --show-toplevel --absolute-git-dir --git-common-dir 2>/dev/null)" || return 1
  top="${out%%"$GATE_NL"*}"
  out="${out#*"$GATE_NL"}"
  git_dir="${out%%"$GATE_NL"*}"
  common="${out#*"$GATE_NL"}"
  [ -n "$top" ] && [ -n "$git_dir" ] && [ -n "$common" ] && [ "$git_dir" != "$out" ] || return 1
  # An older git prints the common directory relative to the directory.
  case "$common" in
    /* | [A-Za-z]:[\\/]*) ;;
    *) common="$1/$common" ;;
  esac
  top="$(physical_dir "$top")" && git_dir="$(physical_dir "$git_dir")" &&
    common="$(physical_dir "$common")" || return 1
  printf '%s\n%s\n%s\n' "$top" "$git_dir" "$common"
}
SESSION_IDENTITY="$(gate_git_identity "$BASE_DIR" || true)"
if [ -n "$SESSION_IDENTITY" ]; then
  gate_exclude_tree "$BASE_DIR" "${SESSION_IDENTITY%%"$GATE_NL"*}"
fi

# Returns 0 only when the strict push in STRICT_ARGS, run in the linked
# worktree $1, cannot send the branch of the session. All of these must hold:
# - The options are only -u, -q, --set-upstream, --force-with-lease and
#   --force-if-includes.
# - The words after the options are [<repository>] [<refspec>...]. The source
#   of each refspec (without a leading + and before the first :) is not empty.
#   For each source, git rev-parse --symbolic-full-name in $1 gives the same
#   ref as for HEAD in $1, and that ref is not the session branch. A commit
#   name, `feat~0` or `@{-1}` gives no ref, so it fails.
# - A push without a refspec needs push.default (read in $1) unset or one of
#   simple, current, upstream and nothing, and no remote with a push or mirror
#   setting.
# Every other result and every git error return 1. The function runs in a
# subshell, so an error under set -u also returns 1 and the session is
# audited.
gate_push_spares_session() (
  local target="$1" word src ref head session_ref push_default rc
  local positionals=0 refspecs=0
  if ! head="$(gate_git -C "$target" rev-parse --symbolic-full-name HEAD 2>/dev/null)"; then
    return 1
  fi
  [ -n "$head" ] || return 1
  # Exit 1 means a detached HEAD: no session branch, so no ref can match it.
  if session_ref="$(gate_git -C "$BASE_DIR" symbolic-ref -q HEAD 2>/dev/null)"; then
    :
  else
    rc=$?
    [ "$rc" -eq 1 ] || return 1
    session_ref=""
  fi
  [ "$head" != "$session_ref" ] || return 1
  for word in ${STRICT_ARGS[@]+"${STRICT_ARGS[@]}"}; do
    case "$word" in
      -u | -q | --set-upstream | --force-with-lease | --force-if-includes) continue ;;
      -*) return 1 ;;
    esac
    positionals=$((positionals + 1))
    # The first word is the repository.
    [ "$positionals" -gt 1 ] || continue
    refspecs=$((refspecs + 1))
    src="${word#+}"
    src="${src%%:*}"
    case "$src" in
      '' | -*) return 1 ;;
    esac
    if ! ref="$(gate_git -C "$target" rev-parse --symbolic-full-name "$src" 2>/dev/null)"; then
      return 1
    fi
    [ -n "$ref" ] && [ "$ref" = "$head" ] && [ "$ref" != "$session_ref" ] || return 1
  done
  if [ "$refspecs" -eq 0 ]; then
    # Exit 1 means that push.default is not set.
    if push_default="$(gate_git -C "$target" config --get push.default 2>/dev/null)"; then
      :
    else
      rc=$?
      [ "$rc" -eq 1 ] || return 1
      push_default=""
    fi
    case "$push_default" in
      '' | simple | current | upstream | nothing) ;;
      *) return 1 ;;
    esac
    # Exit 1 means that no remote has a push or mirror setting.
    if gate_git -C "$target" config --get-regexp '^remote\..*\.(push|mirror)$' >/dev/null 2>&1; then
      return 1
    else
      rc=$?
      [ "$rc" -eq 1 ] || return 1
    fi
  fi
  return 0
)

# Returns 0 when git reports another work tree for a directory than for the
# session directory: both the top level and the git directory differ. With
# `push` as the second argument, the common git directory must differ too,
# because linked worktrees share refs: a push from one of them can send the
# branch or tags of the session. The one exception is a push that
# gate_push_spares_session accepts. A directory in the same work tree, or a
# git error, returns 1.
gate_other_work_tree() {
  local identity top git_dir common session_top session_git_dir session_common rest
  [ -n "$SESSION_IDENTITY" ] || return 1
  identity="$(gate_git_identity "$1")" || return 1
  top="${identity%%"$GATE_NL"*}"
  rest="${identity#*"$GATE_NL"}"
  git_dir="${rest%%"$GATE_NL"*}"
  common="${rest#*"$GATE_NL"}"
  session_top="${SESSION_IDENTITY%%"$GATE_NL"*}"
  rest="${SESSION_IDENTITY#*"$GATE_NL"}"
  session_git_dir="${rest%%"$GATE_NL"*}"
  session_common="${rest#*"$GATE_NL"}"
  [ "$top" != "$session_top" ] && [ "$git_dir" != "$session_git_dir" ] || return 1
  if [ "${2:-}" = push ] && [ "$common" = "$session_common" ]; then
    gate_push_spares_session "$1" || return 1
  fi
  return 0
}

# Prints the subcommand and the target directory of a command in a strict
# form, in which each
# word is inert and the target is certain:
#   [cd <dir> &&] git [-C <dir>]... (commit|push) [<option or name>]...
# A directory is one plain word, or one pair of single or double quotes
# without a new line. A plain word holds only letters, digits and `-_./=:,@+%`
# (no glob, `~` or `{`). A double-quoted word cannot hold `$`, a backquote or
# a backslash. A `-C` directory cannot start with `-`, `+` or `=`, and a `cd`
# directory must start with `/`, `./` or `../`, or be `.` or `..`. After the
# subcommand, only the options in
# gate_inert_option are allowed; a quoted word is allowed only as the value of
# `-m` or `--message`. Nothing else is allowed: no other operator, expansion,
# redirection, environment prefix or git option such as `-c`. Each directory
# must exist. For a push, the words after the subcommand follow, one on each
# line. Returns 1 for any other command.
gate_allowlisted_target() {
  local cmd="$1" rest dir="$BASE_DIR" subcommand word
  # The letters are listed, not given as a range, so that no locale can make
  # the class match a non-ASCII character.
  local plain='[ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_./:@%+,=-]+'
  local sq_dir=$'\'[^\'\n]*\'' dq_dir=$'"[^"$`\\\\\n]*"'
  local sq_arg="'[^']*'" dq_arg='"[^"$`\\]*"'
  local blank=$'[ \t]' sp re word_re dir_re arg_re
  local -a words=() args=()
  sp="$blank+"
  dir_re="($plain|$sq_dir|$dq_dir)"
  arg_re="($plain|$sq_arg|$dq_arg)"
  re="^${blank}*(cd${sp}${dir_re}${sp}[&][&]${sp})?git(${sp}-C${sp}${dir_re})*${sp}(commit|push)(${sp}${arg_re})*${blank}*\$"
  [[ "$cmd" =~ $re ]] || return 1
  word_re="^${blank}*(${plain}|${sq_arg}|${dq_arg}|[&][&])"
  rest="$cmd"
  while [[ "$rest" =~ $word_re ]]; do
    words+=("${BASH_REMATCH[1]}")
    rest="${rest:${#BASH_REMATCH[0]}}"
  done
  set -- "${words[@]}"
  if [ "$1" = cd ]; then
    dir="$(gate_cd_step "$LOGICAL_BASE" "$dir" "$2")" || return 1
    shift 3
  fi
  shift
  while [ "$1" = -C ]; do
    dir="$(gate_c_step "$dir" "$2")" || return 1
    shift 2
  done
  subcommand="$1"
  shift
  while [ "$#" -gt 0 ]; do
    word="$1"
    shift
    case "$word" in
      \'* | \"*) return 1 ;;
    esac
    case "$subcommand:$word" in
      commit:-m | commit:--message | commit:-am)
        # The message: any one word of the grammar, quoted or plain.
        [ "$#" -gt 0 ] || return 1
        shift
        ;;
      *:-*) gate_inert_option "$subcommand" "$word" || return 1 ;;
    esac
    args+=("$word")
  done
  printf '%s\n%s\n' "$subcommand" "$dir"
  if [ "$subcommand" = push ] && [ "${#args[@]}" -gt 0 ]; then
    printf '%s\n' "${args[@]}"
  fi
}

# Options of `git commit` and `git push` that do not run a command, read a
# file, or change the repository or the directory.
gate_inert_option() {
  case "$1:$2" in
    commit:--message=* | commit:-a | commit:--all | commit:--amend | commit:--no-edit | \
      commit:-s | commit:--signoff | commit:--allow-empty | commit:-v | commit:--verbose | \
      commit:-S | commit:-S* | commit:--gpg-sign | commit:--gpg-sign=* | commit:--no-gpg-sign | \
      commit:-q | commit:--quiet | commit:-n | commit:--no-verify) return 0 ;;
    push:-u | push:--set-upstream | push:-f | push:--force | push:--force-with-lease | \
      push:--force-with-lease=* | push:--force-if-includes | push:--tags | push:--follow-tags | push:--dry-run | \
      push:-n | push:-v | push:--verbose | push:-q | push:--quiet | push:--no-verify | \
      push:-d | push:--delete) return 0 ;;
  esac
  return 1
}

# Follows the directory word of a `cd`. Bash resolves `..` from the logical
# path, so the step counts only when the logical and the physical result are
# the same directory. Only an explicit path form is allowed, so CDPATH and
# directory stack forms such as `-` or `+1` never apply.
gate_cd_step() {
  local word logical physical
  word="$(gate_unquote "$3")"
  case "$word" in
    /* | ./* | ../* | . | ..) ;;
    *) return 1 ;;
  esac
  logical="$(CDPATH='' cd -L "$1" 2>/dev/null && CDPATH='' cd -L "$word" 2>/dev/null && pwd -P)" || return 1
  physical="$(CDPATH='' cd -P "$2" 2>/dev/null && CDPATH='' cd -P "$word" 2>/dev/null && pwd -P)" || return 1
  [ "$logical" = "$physical" ] || return 1
  printf '%s\n' "$physical"
}

# Follows the directory word of a `git -C`. Git calls chdir(), which resolves
# `..` physically.
gate_c_step() {
  local word
  word="$(gate_unquote "$2")"
  case "$word" in
    "" | -* | +* | =*) return 1 ;;
  esac
  (CDPATH='' cd -P "$1" 2>/dev/null && CDPATH='' cd -P "$word" 2>/dev/null && pwd -P)
}

# One audit root for each different tree, in order. Without a usable `cwd`,
# an empty root keeps the audit in the process directory without a `cd`,
# exactly as before.
AUDIT_ROOTS=()
add_audit_root() {
  local root="$1" known
  if [ -n "$SESSION_DIR" ]; then
    root="$(resolve_audit_root "$1" "$GATE_REL" "$PROCESS_DIR" "$HOME_DIR")"
  elif [ "$1" = "$PROCESS_DIR" ]; then
    root=""
  else
    root="$(resolve_audit_root "$1" "$GATE_REL" "$PROCESS_DIR" "$HOME_DIR")"
  fi
  if [ "${#AUDIT_ROOTS[@]}" -gt 0 ]; then
    for known in "${AUDIT_ROOTS[@]}"; do
      [ "$known" = "$root" ] && return 0
    done
  fi
  if [ -n "${FALLOW_GATE_DEBUG:-}" ] && [ -n "$SESSION_DIR" ]; then
    if [ "$1" = "$SESSION_DIR" ]; then
      echo "fallow-gate: auditing $root (session directory $SESSION_DIR)." >&2
    else
      echo "fallow-gate: auditing $root (command target $1, session directory $SESSION_DIR)." >&2
    fi
  fi
  AUDIT_ROOTS+=("$root")
  gate_exclude_target "${root:-$PROCESS_DIR}"
}

# A strict command audits its target alone only when git reports another work
# tree for it. Every other git write audits the session directory exactly as
# before. It also audits each candidate directory that git reports in another
# work tree, so a command that the scan reads wrong can only add audits.
STRICT_SUBCOMMAND=""
TARGET_DIR=""
STRICT_ARGS=()
if STRICT="$(gate_allowlisted_target "$CMD")"; then
  STRICT_SUBCOMMAND="${STRICT%%"$GATE_NL"*}"
  STRICT_REST="${STRICT#*"$GATE_NL"}"
  TARGET_DIR="${STRICT_REST%%"$GATE_NL"*}"
  if [ "$STRICT_REST" != "$TARGET_DIR" ]; then
    while IFS= read -r STRICT_WORD; do
      STRICT_ARGS+=("$STRICT_WORD")
    done <<<"${STRICT_REST#*"$GATE_NL"}"
  fi
fi
[ -z "$TARGET_DIR" ] || gate_exclude_target "$TARGET_DIR"
# The session audit stays on until every check for the target passes.
AUDIT_SESSION=1
if [ -n "$TARGET_DIR" ] && gate_other_work_tree "$TARGET_DIR" "$STRICT_SUBCOMMAND"; then
  AUDIT_SESSION=0
fi
if [ "$AUDIT_SESSION" -eq 0 ]; then
  add_audit_root "$TARGET_DIR"
else
  add_audit_root "$BASE_DIR"
  # A strict push from a linked worktree of the same repository can send the
  # refs of the session, so it audits both trees, unless
  # gate_push_spares_session accepted it above.
  if [ -n "$TARGET_DIR" ] && gate_other_work_tree "$TARGET_DIR"; then
    add_audit_root "$TARGET_DIR"
  fi
  if [ "${#GIT_WRITE_CANDIDATES[@]}" -gt 0 ]; then
    for CANDIDATE in "${GIT_WRITE_CANDIDATES[@]}"; do
      CANDIDATE="$(gate_join "$BASE_DIR" "$CANDIDATE")"
      CANDIDATE_DIR="$(CDPATH='' cd -P "$CANDIDATE" 2>/dev/null && pwd -P)" || continue
      gate_exclude_target "$CANDIDATE_DIR"
      if gate_other_work_tree "$CANDIDATE_DIR"; then
        add_audit_root "$CANDIDATE_DIR"
      fi
    done
  fi
fi
gate_check_targets
GATE_PATH_FALLOW="$(gate_which fallow || true)"

# Lists the findings that caused a fail verdict, one line each, from the
# `fallow audit --format json` report on stdin. A finding is an object with an
# `actions` array and a location. Under the default `gate = "new-only"` only
# introduced findings decide the verdict, so the list holds those, first the
# ones that are not warnings. Under `gate = "all"` no finding carries
# `introduced`, so the list holds every finding that is not a warning.
# shellcheck disable=SC2016 # The jq program uses its own $variables.
GATE_FINDINGS_JQ='
def warning: (.effective_severity // .severity // "") as $s | $s == "warn" or $s == "off";
# Some finding types have no `path`, for example an unlisted dependency
# (`imported_from`) or a boundary violation (`from_path`). The `introduced` key
# and the location keys below make sure that the gate counts them.
def finding: type == "object" and (.actions | type) == "array"
  and (has("introduced") or has("path") or has("from_path") or has("file")
    or has("files") or has("instances") or has("locations")
    or has("imported_from") or has("hops") or has("package_roots"));
def lead($key): (.[$key] // [])[0] // {};
def location: .path // .from_path // .file // (.files // [])[0]
  // lead("instances").file // lead("locations").path
  // lead("imported_from").path // lead("hops").file
  // (.package_roots // [])[0] // "?";
def line: .line // lead("instances").start_line // lead("locations").line
  // lead("imported_from").line // lead("hops").line;
def detail: .export_name // .package_name // .member_name // .entry_name // .name
  // .specifier // .import_specifier // .url // .value // .message // "";
# The report holds names and paths from the audited tree. A control character
# (C0, DEL, C1) or a Unicode line or paragraph separator in one of them could
# split a line or send a terminal escape sequence, so each becomes a space.
def clean: tostring | gsub("[\\x{0}-\\x{1f}\\x{7f}-\\x{9f}\\x{2028}\\x{2029}]+"; " ");
def kind($keys): .code // .rule // ((.finding_id // "") | split(":") | .[1])
  // (if $keys[-1] == "findings" or $keys[-1] == "clone_groups" then $keys[0] else $keys[-1] end);
. as $root
| [paths(finding) as $p | {keys: [$p[] | strings], f: ($root | getpath($p))}] as $all
| ($all | map(select(.f.introduced == true))) as $introduced
| (if ($introduced | map(select(.f | warning | not)) | length) > 0
     then $introduced | map(select(.f | warning | not))
   elif ($introduced | length) > 0 then $introduced
   elif ($root.attribution.gate // "") == "all" then $all | map(select(.f | warning | not))
   else [] end)
| .[]
| .keys as $keys
| .f
| "\(kind($keys) | clean) \(location | clean)\(line as $l | if $l == null then "" else ":\($l | clean)" end)\(detail | clean | if . == "" then "" else " \(.)" end)"
'

# The block message lists at most this many findings. The full report holds
# the rest.
GATE_MAX_FINDINGS=50

# The audited tree can hold symbolic links, for example a committed `.fallow`
# link that points to a directory outside the tree. The gate must not write
# through such a link, so the two functions below refuse it.

# Succeeds when no existing component of the relative path $1 is a symbolic
# link. Components resolve against the current directory.
no_symlink_below_pwd() {
  local prefix="." part parts
  IFS=/ read -r -a parts <<<"$1"
  for part in ${parts[@]+"${parts[@]}"}; do
    [ -n "$part" ] || continue
    prefix="$prefix/$part"
    [ ! -L "$prefix" ] || return 1
  done
}

# Succeeds when no existing component of the absolute path $1 is a symbolic
# link that lives in the audited tree (the current directory). A link outside
# the tree, for example a `/tmp` link of the system, is the choice of the
# operator and stays allowed. A link that leads into the tree is followed, and
# each component after it is checked the same way.
no_link_in_absolute_report() {
  local here prefix="" part parts parent
  here="$(pwd -P)" || return 1
  IFS=/ read -r -a parts <<<"$1"
  for part in ${parts[@]+"${parts[@]}"}; do
    [ -n "$part" ] || continue
    prefix="$prefix/$part"
    [ -L "$prefix" ] || continue
    parent="$(CDPATH='' cd -P "$(dirname "$prefix")" 2>/dev/null && pwd -P)" || return 1
    case "$parent" in
      "$here" | "$here"/*) return 1 ;;
    esac
  done
}

# Writes stdin to the file $1. A symbolic link or a directory at $1 makes the
# function fail. The data goes to a temporary file in the target directory, and
# `mv -f` then replaces $1 with that file, so a link to a file that appears after
# the check is replaced, not followed.
write_no_follow() {
  local target="$1" tmp
  [ ! -L "$target" ] && [ ! -d "$target" ] || return 1
  tmp="$(mktemp "$(dirname "$target")/.fallow-gate.XXXXXX")" || return 1
  if cat >"$tmp" && mv -f "$tmp" "$target"; then
    return 0
  fi
  rm -f "$tmp"
  return 1
}

# Prints the block message for the report in $TMP_JSON. The message names the
# findings that caused the block and the path of the full report.
print_block_message() {
  local report="${FALLOW_GATE_REPORT:-.fallow/gate-report.json}" report_path findings count
  case "$report" in
    /*) report_path="$report" ;;
    *) report_path="$(pwd -P)/$report" ;;
  esac
  if ! {
    case "$report" in
      /*) no_link_in_absolute_report "$report" ;;
      *) no_symlink_below_pwd "$report" ;;
    esac && mkdir -p "$(dirname "$report_path")" \
      && write_no_follow "$report_path" <"$TMP_JSON"
  } 2>/dev/null; then
    KEEP_TMP_JSON=1
    report_path="$TMP_JSON"
  elif [ -z "${FALLOW_GATE_REPORT:-}" ] && [ ! -e .fallow/.gitignore ]; then
    # Same self-ignore as the fallow cache directory, so the report never
    # makes the work tree dirty.
    printf '*\n' | write_no_follow .fallow/.gitignore 2>/dev/null || true
  fi
  if [ "${#GATE_JSON_RUNNER[@]}" -gt 0 ]; then
    findings="$(gate_json findings <"$TMP_JSON" 2>/dev/null || true)"
  else
    findings="$(jq -r "$GATE_FINDINGS_JQ" <"$TMP_JSON" 2>/dev/null || true)"
  fi
  count="$(printf '%s' "$findings" | grep -c . || true)"
  {
    echo "fallow-gate: blocked by fallow ${VERSION:-unknown} at $BIN_DESC"
    if [ "$count" -gt 0 ]; then
      echo "fallow-gate: verdict fail, $count finding(s) caused the block:"
      printf '%s\n' "$findings" | sed -n "1,${GATE_MAX_FINDINGS}s/^/  /p"
      if [ "$count" -gt "$GATE_MAX_FINDINGS" ]; then
        echo "  ... and $((count - GATE_MAX_FINDINGS)) more in the full report"
      fi
    else
      echo "fallow-gate: verdict fail. Read the full report for the findings."
    fi
    echo "fallow-gate: full report: $report_path"
  } >&2
}

# Sets VERSION_RAW when the command after the description prints a fallow
# version. A launcher that cannot start (for example an npm shim whose package
# is gone) fails here, so the caller tries the next install. The first failed
# launcher and its first error line stay in BROKEN_DESC and BROKEN_ERR.
BROKEN_DESC=""
BROKEN_ERR=""
fallow_runs() {
  local desc="$1"
  shift
  if VERSION_RAW="$("$@" --version 2>/dev/null)" && [[ "$VERSION_RAW" == fallow* ]]; then
    return 0
  fi
  if [ -z "$BROKEN_DESC" ]; then
    BROKEN_DESC="$desc"
    BROKEN_ERR="$({ "$@" --version 2>&1 >/dev/null || true; } | { IFS= read -r line || true; printf '%s' "$line"; })"
  fi
  return 1
}

run_audit() {
  # The gate runs only a fallow that the install trusts, in this order:
  #   1. The trusted fallow of the install (GATE_LOCAL_FALLOW): the fallow that
  #      wrote a user-scope gate, or the launcher in the node_modules of the
  #      install root of a project-scope gate.
  #   2. The fallow on PATH.
  #   3. Project scope only, when the audit root is the install root: Yarn
  #      Plug'n'Play and `npx --no-install`, which resolve the install of the
  #      project.
  # The gate does not run a launcher of the audited tree or of its parents.
  # Keep this order in step with `agent status` and with the plugin gate of
  # fallow-skills.
  local package_runner=0
  if [ "$GATE_SCOPE" = project ] && [ -n "$GATE_INSTALL_ROOT" ] &&
    [ "$(pwd -P)" = "$GATE_INSTALL_ROOT" ]; then
    package_runner=1
  fi
  if [ "$GATE_SCOPE" = project ]; then
    BIN_FIX="update the fallow devDependency of the project (for example npm install -D fallow@latest)"
  else
    BIN_FIX="upgrade fallow, then run fallow agent install --user again"
  fi
  if [ -n "$GATE_LOCAL_FALLOW" ] && fallow_runs "$GATE_LOCAL_FALLOW" "$GATE_LOCAL_FALLOW"; then
    RUNNER=("$GATE_LOCAL_FALLOW")
    BIN_DESC="$GATE_LOCAL_FALLOW"
  elif [ -n "$GATE_PATH_FALLOW" ] && fallow_runs "$GATE_PATH_FALLOW" "$GATE_PATH_FALLOW"; then
    RUNNER=("$GATE_PATH_FALLOW")
    BIN_DESC="$GATE_PATH_FALLOW"
    BIN_FIX="upgrade the fallow on PATH (for example npm install -g fallow@latest or cargo install fallow-cli)"
  elif [ "$package_runner" -eq 1 ] && command -v yarn >/dev/null 2>&1 && YARN_BIN="$(yarn bin fallow 2>/dev/null)" && [ -n "$YARN_BIN" ] && fallow_runs "yarn exec fallow" yarn exec fallow --; then
    # Yarn Plug'n'Play has no node_modules/.bin at all, so neither the launcher
    # check above nor npx can see the install.
    RUNNER=(yarn exec fallow --)
    BIN_DESC="yarn exec fallow"
  elif [ "$package_runner" -eq 1 ] && command -v npx >/dev/null 2>&1 && VERSION_RAW="$(npx --no-install fallow --version 2>/dev/null || true)" && [[ "$VERSION_RAW" == fallow* ]]; then
    # npx also fails when no install exists, so a failed probe here does not
    # count as a broken launcher.
    RUNNER=(npx --no-install fallow)
    BIN_DESC="npx --no-install fallow"
  elif [ -n "$BROKEN_DESC" ]; then
    {
      echo "fallow-gate: blocked: $BROKEN_DESC cannot print its fallow version (${BROKEN_ERR:-no error output})."
      echo "fallow-gate: the audit cannot run. Reinstall fallow, for example with the install command of the project package manager."
    } >&2
    exit 2
  else
    if [ "$GATE_SCOPE" = project ]; then
      echo "fallow-gate: fallow binary not found (tried the node_modules/.bin of the install root, PATH, yarn and npx --no-install), skipping audit." >&2
    else
      echo "fallow-gate: fallow binary not found (tried the fallow that installed the gate and PATH), skipping audit." >&2
    fi
    exit 0
  fi

  # The npm launcher prints a `verified:` line after the version line, so
  # only the first line holds the version.
  VERSION="$(printf '%s\n' "$VERSION_RAW" | head -n 1)"
  VERSION="${VERSION#fallow }"
  VERSION="${VERSION%% *}"

  MIN_VERSION="${FALLOW_GATE_MIN_VERSION-2.85.0}"
  if [ -n "$MIN_VERSION" ] && [ -n "$VERSION" ]; then
    LOWER="$(printf '%s\n%s\n' "$MIN_VERSION" "$VERSION" | sort -V | head -n1)"
    if [ "$LOWER" != "$MIN_VERSION" ]; then
      {
        echo "fallow-gate: blocked: $BIN_DESC is fallow $VERSION, below required $MIN_VERSION."
        echo "fallow-gate: older binaries reject the --gate-marker flag this gate passes"
        echo "fallow-gate: (added in fallow v2.85.0), so the audit cannot run."
        echo "fallow-gate: $BIN_FIX,"
        echo "fallow-gate: or set FALLOW_GATE_MIN_VERSION= to disable."
      } >&2
      exit 2
    fi
  fi

  TMP_JSON="$(mktemp)"
  TMP_ERR="$(mktemp)"
  KEEP_TMP_JSON=""
  # shellcheck disable=SC2329 # Called by the EXIT trap.
  cleanup() {
    rm -f "$TMP_ERR"
    # The block message can point at the temporary report when the report
    # path is not writable, so that report stays.
    [ -n "$KEEP_TMP_JSON" ] || rm -f "$TMP_JSON"
  }
  trap cleanup EXIT

  if "${RUNNER[@]}" audit --format json --quiet --explain --gate-marker agent >"$TMP_JSON" 2>"$TMP_ERR"; then
    STATUS=0
  else
    STATUS=$?
  fi

  MSG=""
  if [ "${#GATE_JSON_RUNNER[@]}" -gt 0 ]; then
    GATE_RESULT="$(mktemp)"
    if ! gate_json report <"$TMP_JSON" >"$GATE_RESULT"; then
      rm -f "$GATE_RESULT"
      echo "fallow-gate: cannot read audit report, skipping." >&2
      exit 0
    fi
    {
      IFS= read -r -d '' VERDICT
      IFS= read -r -d '' IS_ERROR
      IFS= read -r -d '' MSG
    } <"$GATE_RESULT"
    rm -f "$GATE_RESULT"
  else
    VERDICT="$(jq -r '.verdict // empty' <"$TMP_JSON" 2>/dev/null || true)"
    IS_ERROR="$(jq -r '.error // false' <"$TMP_JSON" 2>/dev/null || echo false)"
    MSG="$(jq -r '.message // empty' <"$TMP_JSON" 2>/dev/null || true)"
  fi

  if [ "$VERDICT" = "fail" ]; then
    if [ "${FALLOW_GATE_OUTPUT:-}" = "json" ]; then
      echo "fallow-gate: blocked by fallow ${VERSION:-unknown} at $BIN_DESC" >&2
      cat "$TMP_JSON" >&2
    else
      print_block_message
    fi
    exit 2
  fi

  if [ "$STATUS" -eq 2 ] || [ "$IS_ERROR" = "true" ]; then
    if [ -n "$MSG" ]; then
      echo "fallow-gate: fallow audit runtime error ($MSG), skipping." >&2
    else
      echo "fallow-gate: fallow audit runtime error, skipping." >&2
    fi
    exit 0
  fi

  if [ "$STATUS" -ne 0 ]; then
    ERR_LINE="$(sed -n '1p' "$TMP_ERR" 2>/dev/null || true)"
    if [ -n "$ERR_LINE" ]; then
      echo "fallow-gate: fallow audit exited $STATUS ($ERR_LINE), skipping." >&2
    else
      echo "fallow-gate: fallow audit exited $STATUS, skipping." >&2
    fi
    exit 0
  fi
}

# Each audit runs in a subshell, so its `cd`, `exit` and cleanup trap stay
# local to that audit root. Each root gets the same block rule as a single
# audit: exit 2 blocks. Any other failure of one root does not stop the
# audits of the other roots, and the gate exits with it at the end.
FINAL_STATUS=0
for AUDIT_ROOT in "${AUDIT_ROOTS[@]}"; do
  set +e
  (
    set -e
    if [ -n "$AUDIT_ROOT" ] && ! CDPATH='' cd -P "$AUDIT_ROOT" 2>/dev/null; then
      echo "fallow-gate: cannot enter $AUDIT_ROOT, auditing $(pwd) instead." >&2
    fi
    run_audit
  )
  AUDIT_STATUS=$?
  set -e
  if [ "$AUDIT_STATUS" -eq 2 ]; then
    exit 2
  fi
  if [ "$AUDIT_STATUS" -ne 0 ] && [ "$FINAL_STATUS" -eq 0 ]; then
    FINAL_STATUS="$AUDIT_STATUS"
  fi
done

exit "$FINAL_STATUS"
